# pipeline/transforms/enrich.py
def build_customer_index(customers: pd.DataFrame) -> dict[int, CustomerRow]:
    return {row.customer_id: row for row in customers.itertuples(index=False)}

def enrich_orders(orders: pd.DataFrame, customers: pd.DataFrame) -> pd.DataFrame:
    customer_index = build_customer_index(customers)
    orders = orders.copy()
    orders["customer_segment"] = orders["customer_id"].map(
        lambda cid: customer_index.get(cid).segment if cid in customer_index else None
    )
    orders["customer_region"] = orders["customer_id"].map(
        lambda cid: customer_index.get(cid).region if cid in customer_index else None
    )
    return add_window_features(orders)

# pipeline/jobs/orders_job.py
def run(date: str) -> None:
    shard_paths = list_order_shards(date)
    frames = []
    for path in shard_paths:
        frames.append(normalize_orders(read_order_shard(path)))
    all_orders = pd.concat(frames, ignore_index=True)
    customers = load_customer_dimension()
    enriched = enrich_orders(all_orders, customers)
    PostgresOrderWriter().write_dataframe(enriched)

# pipeline/loaders/postgres.py
class PostgresOrderWriter:
    def __init__(self, batch_size: int = 50000) -> None:
        self.batch_size = batch_size
        self._rows_buffer: list[dict[str, object]] = []

    def write_dataframe(self, df: pd.DataFrame) -> None:
        self._rows_buffer.extend(df.to_dict("records"))
        if len(self._rows_buffer) >= self.batch_size:
            self.flush()

    def flush(self) -> None:
        rows = [tuple(row[col] for col in ORDER_COLUMNS) for row in self._rows_buffer]
        with self.conn.cursor() as cur:
            cur.executemany(SQL, rows)
        self._rows_buffer.clear()
